<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;
class StoreAssetLoanRequest extends FormRequest{public function authorize():bool{return $this->user()?->isAdmin()===true;}public function rules():array{return ['asset_id'=>['required','integer','exists:assets,id'],'borrower_name'=>['required','string','max:255'],'borrower_role'=>['nullable','string','max:100'],'borrower_phone'=>['nullable','string','max:30'],'quantity'=>['required','integer','min:1'],'loan_date'=>['required','date'],'expected_return_date'=>['nullable','date','after_or_equal:loan_date'],'purpose'=>['nullable','string','max:2000'],'notes'=>['nullable','string','max:2000']];}public function messages():array{return ['asset_id.required'=>'Aset wajib dipilih.','borrower_name.required'=>'Nama peminjam wajib diisi.','quantity.required'=>'Jumlah pinjam wajib diisi.','quantity.integer'=>'Jumlah pinjam harus berupa angka bulat.','quantity.min'=>'Jumlah pinjam minimal 1.','loan_date.required'=>'Tanggal pinjam wajib diisi.','loan_date.date'=>'Tanggal pinjam tidak valid.','expected_return_date.after_or_equal'=>'Rencana kembali tidak boleh sebelum tanggal pinjam.'];}}
